CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_complete_step(p_owner_account_id text, p_token_hash text, p_generation integer, p_expected_cursor text, p_next_cursor text, p_detail jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_job     public.yorisou_account_deletion_jobs%rowtype;
  v_from    integer;
  v_to      integer;
  v_gate    public.yorisou_account_mutation_gates%rowtype;
  v_active  integer;
  v_crossing boolean;
  v_state   text;
begin
  v_job := public.yorisou_account_deletion_require_executor(p_owner_account_id, p_token_hash, p_generation);

  if v_job.execution_cursor is distinct from p_expected_cursor then
    raise exception 'account_deletion_cursor_mismatch_expected_%_actual_%',
      p_expected_cursor, coalesce(v_job.execution_cursor, 'null');
  end if;

  v_from := public.yorisou_account_deletion_stage_rank(p_expected_cursor);
  v_to   := public.yorisou_account_deletion_stage_rank(p_next_cursor);
  if v_from is null or v_to is null then
    raise exception 'account_deletion_unknown_stage';
  end if;
  -- Exactly one forward. A skip would mark work done that never ran; a backward move would replay a
  -- stage that has already written — which is how an erased identity came back.
  if v_to <> v_from + 1 then
    raise exception 'account_deletion_illegal_cursor_%_to_%', p_expected_cursor, p_next_cursor;
  end if;

  v_crossing := v_to >= public.yorisou_account_deletion_irreversible_rank();

  -- THE MUTATION-LEASE INVARIANT. Anything at or past the crossing requires a gate that is closed
  -- with nothing outstanding — re-checked at EVERY step, not just at the crossing, because a lease
  -- taken after the close would otherwise sit unnoticed alongside a running erasure.
  if v_crossing then
    select * into v_gate from public.yorisou_account_mutation_gates
     where owner_account_id = p_owner_account_id;
    if not found or v_gate.gate_state not in ('closed','completed') then
      raise exception 'account_deletion_gate_not_closed';
    end if;
    select count(*) into v_active from public.yorisou_account_mutation_leases
     where owner_account_id = p_owner_account_id
       and released_at is null and drained_at is null;
    if v_active > 0 then
      raise exception 'account_deletion_gate_not_drained_%', v_active;
    end if;
  end if;

  -- The crossing itself also demands the manifest, because every stage after it depends on one.
  if v_to = public.yorisou_account_deletion_irreversible_rank() then
    if not exists (select 1 from public.yorisou_account_deletion_manifests where job_id = v_job.id) then
      raise exception 'account_deletion_manifest_missing';
    end if;
  end if;

  v_state := public.yorisou_account_deletion_state_for_cursor(p_next_cursor);

  update public.yorisou_account_deletion_jobs
     set execution_cursor = p_next_cursor,
         -- Set ONCE, at the crossing. `coalesce` is the whole guarantee: no later step and no retry
         -- can move it, and nothing can clear it.
         irreversible_started_at = case
           when v_crossing then coalesce(irreversible_started_at, now())
           else irreversible_started_at end,
         state = coalesce(v_state, state),
         locked_at = case when p_next_cursor = 'lock_marker' then coalesce(locked_at, now()) else locked_at end,
         -- A successful step clears the previous attempt's error. The attempt COUNT is kept: it is
         -- the history of the job, not the status of this run.
         last_error_code = null,
         updated_at = now()
   where id = v_job.id
  returning * into v_job;

  insert into public.yorisou_account_deletion_audit (job_id, stage, outcome, detail)
  values (v_job.id, p_next_cursor, 'ok',
          jsonb_build_object('from', p_expected_cursor, 'generation', p_generation)
          || coalesce(p_detail, '{}'::jsonb));

  return jsonb_build_object(
    'cursor', v_job.execution_cursor,
    'state', v_job.state,
    'irreversible', v_job.irreversible_started_at is not null
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_drain_gate(p_owner_account_id text, p_token_hash text, p_generation integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_job public.yorisou_account_deletion_jobs%rowtype;
        v_gate public.yorisou_account_mutation_gates%rowtype;
        v_active integer;
begin
  v_job := public.yorisou_account_deletion_require_executor(p_owner_account_id, p_token_hash, p_generation);

  insert into public.yorisou_account_mutation_gates (owner_account_id)
  values (p_owner_account_id) on conflict (owner_account_id) do nothing;

  select * into v_gate from public.yorisou_account_mutation_gates
   where owner_account_id = p_owner_account_id for update;

  if v_gate.gate_state = 'open' then
    update public.yorisou_account_mutation_gates
       set gate_state = 'draining', generation = generation + 1, updated_at = now()
     where owner_account_id = p_owner_account_id
    returning * into v_gate;
  end if;

  -- Abandon ONLY what cannot still be executing: expired PLUS the full execution grace. An expired
  -- lease inside the grace still blocks, because expiry proves the TTL elapsed, not that the process
  -- holding it has stopped running.
  update public.yorisou_account_mutation_leases
     set drained_at = now()
   where owner_account_id = p_owner_account_id
     and released_at is null
     and drained_at is null
     and expires_at + public.yorisou_account_mutation_execution_grace()
         < public.yorisou_account_mutation_clock();

  select count(*) into v_active from public.yorisou_account_mutation_leases
   where owner_account_id = p_owner_account_id
     and released_at is null and drained_at is null;

  if v_active = 0 and v_gate.gate_state = 'draining' then
    update public.yorisou_account_mutation_gates
       set gate_state = 'closed', closed_at = now(), updated_at = now()
     where owner_account_id = p_owner_account_id
    returning * into v_gate;
  end if;

  if v_gate.gate_state = 'closed' and v_active = 0 then
    update public.yorisou_account_deletion_jobs
       set mutation_gate_closed_at = coalesce(mutation_gate_closed_at, now()), updated_at = now()
     where id = v_job.id;
  end if;

  return jsonb_build_object(
    'gateState',  v_gate.gate_state,
    'generation', v_gate.generation,
    'activeLeases', v_active,
    'drained', v_active = 0 and v_gate.gate_state = 'closed'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_erase_database(p_owner_account_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id       uuid;
  v_plan     text[][] := array[
    -- identity-linked tables, owner column. Legacy AND canonical families both appear: a person's
    -- deletion must not depend on which generation of the product created the row.
    ['yorisou_test_results','owner_account_id'],
    ['yorisou_ai_reflections','owner_account_id'],
    ['yorisou_ai_runs','owner_account_id'],
    ['yorisou_daily_state_history_events','owner_account_id'],
    ['yorisou_daily_state_record_versions','record_id_owner_indirect'],   -- handled via parent below
    ['yorisou_daily_state_records','owner_account_id'],
    ['yorisou_values_assessment_events','owner_account_id'],
    ['yorisou_values_assessment_versions','assessment_id_owner_indirect'],-- handled via parent below
    ['yorisou_values_assessments','owner_account_id'],
    ['yorisou_private_check_in_plans','owner_account_id'],
    ['yorisou_private_memory_items','owner_account_id'],
    ['yorisou_private_recommendations','owner_account_id'],
    ['yorisou_experience_cards','owner_account_id'],
    ['yorisou_experience_consents','owner_account_id'],
    ['yorisou_experience_invites','owner_account_id'],
    ['yorisou_experience_revisions','owner_account_id'],
    ['yorisou_experience_visibility_events','owner_account_id'],
    ['yorisou_experience_events','actor_account_id'],
    ['yorisou_experience_interactions','actor_account_id'],
    ['yorisou_experience_moderation_events','actor_account_id'],
    ['yorisou_experience_reports','reporter_account_id'],
    ['yorisou_experience_blocks','blocker_account_id'],
    ['yorisou_experience_blocks','blocked_owner_account_id'],
    ['yorisou_recommendation_events','owner_account_id'],
    ['yorisou_recommendation_reports','owner_account_id'],
    ['yorisou_recommendation_returns','owner_account_id'],
    ['yorisou_recommendation_actions','owner_account_id'],
    ['yorisou_recommendation_sets','owner_account_id'],
    ['yorisou_canonical_recommendation_actions','owner_account_id'],
    ['yorisou_canonical_recommendation_items','owner_account_id'],
    ['yorisou_canonical_recommendation_sets','owner_account_id'],
    ['yorisou_account_deletion_requests','owner_account_id']
  ];
  v_i        integer;
  v_table    text;
  v_column   text;
  v_count    bigint;
  v_counts   jsonb := '{}'::jsonb;
  v_result   record;
begin
  select id into v_id from public.yorisou_account_deletion_jobs
   where owner_account_id = p_owner_account_id;
  if not found then raise exception 'account_deletion_job_not_found'; end if;

  -- 5.1 Canonical RESULTS go through the governed owner-scoped erasure, which clears the
  --     reconstructable content and leaves the contractual content-free tombstone. Deleting them
  --     outright here would quietly weaken the erasure contract the product publishes.
  if to_regclass('public.yorisou_assessment_results') is not null then
    v_count := 0;
    for v_result in
      select id from public.yorisou_assessment_results
       where owner_account_id = p_owner_account_id and deleted_at is null
    loop
      perform public.yorisou_assessment_result_erase(v_result.id, p_owner_account_id);
      v_count := v_count + 1;
    end loop;
    v_counts := v_counts || jsonb_build_object('yorisou_assessment_results_erased', v_count);
  end if;

  -- 5.2 Attempts hold the raw answers; they are removed, not tombstoned.
  if to_regclass('public.yorisou_assessment_attempts') is not null then
    delete from public.yorisou_assessment_attempts where owner_account_id = p_owner_account_id;
    get diagnostics v_count = row_count;
    v_counts := v_counts || jsonb_build_object('yorisou_assessment_attempts', v_count);
  end if;

  -- 5.3 Child rows whose ownership is only reachable through a parent.
  if to_regclass('public.yorisou_daily_state_record_versions') is not null
     and to_regclass('public.yorisou_daily_state_records') is not null then
    delete from public.yorisou_daily_state_record_versions v
     where exists (select 1 from public.yorisou_daily_state_records r
                    where r.id = v.record_id and r.owner_account_id = p_owner_account_id);
    get diagnostics v_count = row_count;
    v_counts := v_counts || jsonb_build_object('yorisou_daily_state_record_versions', v_count);
  end if;

  if to_regclass('public.yorisou_values_assessment_versions') is not null
     and to_regclass('public.yorisou_values_assessments') is not null then
    delete from public.yorisou_values_assessment_versions v
     where exists (select 1 from public.yorisou_values_assessments a
                    where a.id = v.assessment_id and a.owner_account_id = p_owner_account_id);
    get diagnostics v_count = row_count;
    v_counts := v_counts || jsonb_build_object('yorisou_values_assessment_versions', v_count);
  end if;

  -- 5.4 The declarative plan.
  for v_i in 1 .. array_length(v_plan, 1) loop
    v_table  := v_plan[v_i][1];
    v_column := v_plan[v_i][2];
    if v_column like '%_owner_indirect' then continue; end if;   -- handled above
    if to_regclass('public.' || v_table) is null then
      v_counts := v_counts || jsonb_build_object(v_table, 'absent');
      continue;
    end if;
    if not exists (select 1 from information_schema.columns
                    where table_schema='public' and table_name=v_table and column_name=v_column) then
      v_counts := v_counts || jsonb_build_object(v_table, 'column_absent');
      continue;
    end if;
    execute format('delete from public.%I where %I = $1', v_table, v_column) using p_owner_account_id;
    get diagnostics v_count = row_count;
    v_counts := v_counts || jsonb_build_object(
      case when v_counts ? v_table then v_table || ':' || v_column else v_table end, v_count);
  end loop;

  insert into public.yorisou_account_deletion_audit (job_id, stage, outcome, detail)
  values (v_id, 'database_erasure', 'ok', jsonb_build_object('counts', v_counts));

  return v_counts;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_executor_claim(p_owner_account_id text, p_token_hash text, p_ttl_seconds integer DEFAULT 90)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_job public.yorisou_account_deletion_jobs%rowtype; v_cursor text;
begin
  if p_owner_account_id is null or char_length(p_owner_account_id) = 0 then
    raise exception 'account_deletion_owner_required';
  end if;
  if p_token_hash is null or char_length(p_token_hash) < 32 then
    raise exception 'account_deletion_executor_token_required';
  end if;
  if p_ttl_seconds is null or p_ttl_seconds < 5 or p_ttl_seconds > 600 then
    raise exception 'account_deletion_executor_ttl_out_of_range';
  end if;

  select * into v_job from public.yorisou_account_deletion_jobs
   where owner_account_id = p_owner_account_id for update;
  if not found then raise exception 'account_deletion_job_not_found'; end if;

  if v_job.state in ('completed','cancelled','failed_terminal','legal_hold') then
    raise exception 'account_deletion_not_claimable_%', v_job.state;
  end if;

  -- Someone else is driving, and their claim has not lapsed.
  if v_job.executor_token_hash is not null
     and v_job.executor_token_hash <> p_token_hash
     and v_job.executor_expires_at is not null
     and v_job.executor_expires_at > now() then
    return jsonb_build_object(
      'claimed', false,
      'reason', 'executor_already_claimed',
      'generation', v_job.executor_generation,
      'cursor', v_job.execution_cursor,
      'irreversible', v_job.irreversible_started_at is not null
    );
  end if;

  -- First run of a job that has only been opened and verified.
  v_cursor := coalesce(v_job.execution_cursor, 'mutation_draining');

  update public.yorisou_account_deletion_jobs
     set executor_token_hash = p_token_hash,
         -- Bumped on EVERY claim, including a re-claim by the same executor: a token is not a
         -- generation, and a stale in-flight step from an earlier claim must fail even when the
         -- worker that issued it is the one claiming now.
         executor_generation = executor_generation + 1,
         executor_claimed_at = now(),
         executor_expires_at = now() + make_interval(secs => p_ttl_seconds),
         execution_cursor    = v_cursor,
         updated_at          = now()
   where id = v_job.id
  returning * into v_job;

  return jsonb_build_object(
    'claimed', true,
    'generation', v_job.executor_generation,
    'cursor', v_job.execution_cursor,
    'state', v_job.state,
    'irreversible', v_job.irreversible_started_at is not null,
    'attemptCount', v_job.attempt_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_executor_renew(p_owner_account_id text, p_token_hash text, p_generation integer, p_ttl_seconds integer DEFAULT 90)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_rows integer;
begin
  if p_ttl_seconds is null or p_ttl_seconds < 5 or p_ttl_seconds > 600 then
    raise exception 'account_deletion_executor_ttl_out_of_range';
  end if;
  update public.yorisou_account_deletion_jobs
     set executor_expires_at = now() + make_interval(secs => p_ttl_seconds), updated_at = now()
   where owner_account_id = p_owner_account_id
     and executor_token_hash = p_token_hash
     and executor_generation = p_generation
     and executor_expires_at > now();
  get diagnostics v_rows = row_count;
  return v_rows = 1;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_finalize(p_owner_account_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_state text; v_left jsonb;
begin
  select id, state into v_id, v_state from public.yorisou_account_deletion_jobs
   where owner_account_id = p_owner_account_id for update;
  if not found then raise exception 'account_deletion_job_not_found'; end if;
  if v_state <> 'verifying' then raise exception 'account_deletion_not_verifying'; end if;

  v_left := public.yorisou_account_deletion_verify_database(p_owner_account_id);
  if v_left <> '{}'::jsonb then
    update public.yorisou_account_deletion_jobs
       set state='failed_retryable', last_error_code='verification_residue',
           attempt_count=attempt_count+1, updated_at=now()
     where id = v_id;
    insert into public.yorisou_account_deletion_audit (job_id, stage, outcome, detail)
    values (v_id, 'verifying', 'failed', jsonb_build_object('residue', v_left));
    return false;
  end if;

  update public.yorisou_account_deletion_jobs
     set state='completed', owner_account_id=null, completed_at=now(), updated_at=now()
   where id = v_id;
  insert into public.yorisou_account_deletion_audit (job_id, stage, outcome)
  values (v_id, 'completed', 'ok');
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_finalize_step(p_owner_account_id text, p_token_hash text, p_generation integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_job public.yorisou_account_deletion_jobs%rowtype; v_left jsonb;
begin
  v_job := public.yorisou_account_deletion_require_executor(p_owner_account_id, p_token_hash, p_generation);

  if v_job.execution_cursor is distinct from 'finalizing' then
    raise exception 'account_deletion_cursor_mismatch_expected_finalizing_actual_%',
      coalesce(v_job.execution_cursor, 'null');
  end if;

  v_left := public.yorisou_account_deletion_verify_database(p_owner_account_id);
  if v_left <> '{}'::jsonb then
    update public.yorisou_account_deletion_jobs
       set state='failed_retryable', last_error_code='verification_residue',
           attempt_count = attempt_count + 1, updated_at = now()
     where id = v_job.id;      -- cursor preserved: the retry re-runs finalizing, nothing earlier
    insert into public.yorisou_account_deletion_audit (job_id, stage, outcome, detail)
    values (v_job.id, 'finalizing', 'failed', jsonb_build_object('residue', v_left));
    return jsonb_build_object('completed', false, 'residue', v_left);
  end if;

  update public.yorisou_account_deletion_jobs
     set state = 'completed',
         execution_cursor = 'completed',
         owner_account_id = null,
         completed_at = now(),
         executor_token_hash = null,
         executor_expires_at = null,
         updated_at = now()
   where id = v_job.id;

  insert into public.yorisou_account_deletion_audit (job_id, stage, outcome)
  values (v_job.id, 'completed', 'ok');

  return jsonb_build_object('completed', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_manifest_put(p_owner_account_id text, p_token_hash text, p_generation integer, p_payload jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_job public.yorisou_account_deletion_jobs%rowtype;
begin
  v_job := public.yorisou_account_deletion_require_executor(p_owner_account_id, p_token_hash, p_generation);

  if v_job.irreversible_started_at is not null then
    raise exception 'account_deletion_manifest_frozen';
  end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'account_deletion_manifest_invalid';
  end if;

  insert into public.yorisou_account_deletion_manifests (job_id, payload)
  values (v_job.id, p_payload)
  on conflict (job_id) do nothing;   -- immutable: a second write is a no-op, never an overwrite
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_mutation_gate_status(p_owner_account_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_state text; v_gen integer; v_active integer;
begin
  select gate_state, generation into v_state, v_gen
    from public.yorisou_account_mutation_gates where owner_account_id = p_owner_account_id;
  select count(*) into v_active from public.yorisou_account_mutation_leases
   where owner_account_id = p_owner_account_id and released_at is null and drained_at is null;
  return jsonb_build_object(
    'gateState', coalesce(v_state, 'open'),
    'generation', coalesce(v_gen, 1),
    'activeLeases', v_active
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_open(p_owner_account_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_state text;
begin
  if p_owner_account_id is null or char_length(p_owner_account_id) = 0 then
    raise exception 'account_deletion_owner_required';
  end if;

  select id, state into v_id, v_state
    from public.yorisou_account_deletion_jobs
   where owner_account_id = p_owner_account_id
   for update;

  if found then
    if v_state = 'legal_hold'      then raise exception 'account_deletion_legal_hold'; end if;
    if v_state = 'failed_terminal' then raise exception 'account_deletion_failed_terminal'; end if;
    -- A cancelled job may be reopened; anything else in flight is simply returned.
    if v_state = 'cancelled' then
      update public.yorisou_account_deletion_jobs
         set state='requested', cancelled_at=null, last_error_code=null, updated_at=now()
       where id = v_id;
    end if;
    return v_id;
  end if;

  begin
    insert into public.yorisou_account_deletion_jobs (owner_account_id, owner_fingerprint)
    values (p_owner_account_id, public.yorisou_account_deletion_fingerprint(p_owner_account_id))
    returning id into v_id;

    insert into public.yorisou_account_deletion_audit (job_id, stage, outcome)
    values (v_id, 'requested', 'ok');
    return v_id;
  exception when unique_violation then
    -- The index serialized us. Re-read under a lock: by now the winner has committed, so this is a
    -- genuine read of their row and not a second guess at the race.
    select id, state into v_id, v_state
      from public.yorisou_account_deletion_jobs
     where owner_account_id = p_owner_account_id
     for update;

    if not found then
      -- A unique violation with no surviving row means the winner's transaction rolled back after
      -- claiming the key. Nothing can be returned honestly, and inventing a job would be worse.
      raise exception 'account_deletion_open_lost_race';
    end if;

    -- The refusals are not skipped just because we arrived here the hard way.
    if v_state = 'legal_hold'      then raise exception 'account_deletion_legal_hold'; end if;
    if v_state = 'failed_terminal' then raise exception 'account_deletion_failed_terminal'; end if;
    if v_state = 'cancelled' then
      update public.yorisou_account_deletion_jobs
         set state='requested', cancelled_at=null, last_error_code=null, updated_at=now()
       where id = v_id;
    end if;

    -- No second audit row. The winner already recorded `requested`; a duplicate would read as two
    -- people asking to be deleted.
    return v_id;
  end;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_require_executor(p_owner_account_id text, p_token_hash text, p_generation integer)
 RETURNS yorisou_account_deletion_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_job public.yorisou_account_deletion_jobs%rowtype;
begin
  select * into v_job from public.yorisou_account_deletion_jobs
   where owner_account_id = p_owner_account_id for update;
  if not found then raise exception 'account_deletion_job_not_found'; end if;

  if v_job.executor_token_hash is null or v_job.executor_token_hash <> p_token_hash then
    raise exception 'account_deletion_executor_not_owner';
  end if;
  if v_job.executor_generation <> p_generation then
    raise exception 'account_deletion_executor_stale_generation';
  end if;
  if v_job.executor_expires_at is null or v_job.executor_expires_at <= now() then
    raise exception 'account_deletion_executor_lease_expired';
  end if;
  return v_job;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_terminal_deidentify(p_owner_account_id text, p_reason text DEFAULT 'manifest_missing_pre_irreversible'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_job public.yorisou_account_deletion_jobs%rowtype;
  v_now timestamptz := now();
  v_has_manifest boolean;
  v_claim_live boolean;
begin
  if p_owner_account_id is null or char_length(p_owner_account_id) = 0 then
    raise exception 'account_deletion_owner_required';
  end if;

  select * into v_job from public.yorisou_account_deletion_jobs
   where owner_account_id = p_owner_account_id
   for update;

  if not found then
    -- Idempotent: a job already de-identified no longer carries the id, so there is nothing to find
    -- and nothing to do. Reporting this as an error would make a safe repeat look like a fault.
    return jsonb_build_object('deidentified', false, 'outcome', 'absent_or_already_deidentified');
  end if;

  -- ── ELIGIBILITY. Every clause refuses a DIFFERENT way of getting this wrong. ──

  -- Only a terminal failure. A completed job has its own de-identification; anything live is work
  -- in progress and must keep the id every operation looks it up by.
  if v_job.state is distinct from 'failed_terminal' then
    raise exception 'terminal_deidentify_refused_state_%', v_job.state;
  end if;

  -- NOTHING MAY HAVE BEEN DESTROYED. Past the crossing, the job is the only record of what was
  -- erased and for whom; minimising it there would destroy the audit trail of a real deletion.
  if v_job.irreversible_started_at is not null then
    raise exception 'terminal_deidentify_refused_irreversible';
  end if;

  -- The cursor is the second, independent witness to the same question. `irreversible_started_at`
  -- is the recorded fact; a cursor at or past the crossing would contradict it, and a contradiction
  -- is not something to resolve in favour of deleting identity.
  if v_job.execution_cursor is not null
     and public.yorisou_account_deletion_stage_rank(v_job.execution_cursor)
         >= public.yorisou_account_deletion_irreversible_rank() then
    raise exception 'terminal_deidentify_refused_cursor_%', v_job.execution_cursor;
  end if;

  -- A frozen manifest means the job CAN still be resumed, so it must be — resuming is strictly
  -- better than minimising a failure that did not have to be final.
  select exists (select 1 from public.yorisou_account_deletion_manifests where job_id = v_job.id)
    into v_has_manifest;
  if v_has_manifest then
    raise exception 'terminal_deidentify_refused_manifest_present';
  end if;

  -- Someone may be driving it right now.
  v_claim_live := v_job.executor_token_hash is not null
                  and v_job.executor_expires_at is not null
                  and v_job.executor_expires_at > v_now;
  if v_claim_live then
    raise exception 'terminal_deidentify_refused_executor_held';
  end if;

  if p_reason is distinct from 'manifest_missing_pre_irreversible' then
    raise exception 'terminal_deidentify_refused_reason_%', coalesce(p_reason, 'null');
  end if;

  -- ── THE MINIMISATION ────────────────────────────────────────────────────────
  --
  -- The fingerprint stays: it is one-way, it is what the replay and authentication checks already
  -- consult, and it lets this failure still be recognised without naming anyone. `last_error_code`
  -- stays because a failure record that cannot say why it failed is not an audit record.
  update public.yorisou_account_deletion_jobs
     set owner_account_id = null,
         executor_token_hash = null,
         executor_expires_at = null,
         terminal_deidentified_at = v_now,
         terminal_deidentification_reason = p_reason,
         updated_at = v_now
   where id = v_job.id;

  insert into public.yorisou_account_deletion_audit (job_id, stage, outcome, detail)
  values (v_job.id, 'terminal_deidentified', 'ok',
          jsonb_build_object('reason', p_reason, 'from_state', v_job.state));

  return jsonb_build_object('deidentified', true, 'outcome', 'terminal_deidentified');
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_account_deletion_verify_database(p_owner_account_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tables text[] := array[
    'yorisou_test_results','yorisou_ai_reflections','yorisou_ai_runs',
    'yorisou_daily_state_records','yorisou_values_assessments',
    'yorisou_private_check_in_plans','yorisou_private_memory_items','yorisou_private_recommendations',
    'yorisou_experience_cards','yorisou_recommendation_sets','yorisou_recommendation_actions',
    'yorisou_canonical_recommendation_sets','yorisou_canonical_recommendation_items',
    'yorisou_canonical_recommendation_actions','yorisou_assessment_attempts',
    'yorisou_account_deletion_requests'
  ];
  v_t text; v_n bigint; v_left jsonb := '{}'::jsonb;
begin
  foreach v_t in array v_tables loop
    if to_regclass('public.' || v_t) is null then continue; end if;
    execute format('select count(*) from public.%I where owner_account_id = $1', v_t)
      into v_n using p_owner_account_id;
    if v_n > 0 then v_left := v_left || jsonb_build_object(v_t, v_n); end if;
  end loop;

  -- Results may survive ONLY as content-free tombstones, and a tombstone has no owner by contract.
  if to_regclass('public.yorisou_assessment_results') is not null then
    select count(*) into v_n from public.yorisou_assessment_results
     where owner_account_id = p_owner_account_id;
    if v_n > 0 then v_left := v_left || jsonb_build_object('yorisou_assessment_results_owned', v_n); end if;
  end if;

  return v_left;   -- '{}' means clean
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_account_mutation_begin(p_owner_account_id text, p_operation_code text, p_ttl_seconds integer DEFAULT 30, p_request_nonce_hash text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_gate  public.yorisou_account_mutation_gates%rowtype;
  v_job   public.yorisou_account_deletion_jobs%rowtype;
  v_lease uuid;
begin
  if p_owner_account_id is null or char_length(p_owner_account_id) = 0 then
    raise exception 'account_mutation_owner_required';
  end if;
  if p_ttl_seconds is null or p_ttl_seconds < 1 or p_ttl_seconds > 120 then
    raise exception 'account_mutation_ttl_out_of_range';
  end if;

  select * into v_job from public.yorisou_account_deletion_jobs
   where owner_account_id = p_owner_account_id
      or owner_fingerprint = public.yorisou_account_deletion_fingerprint(p_owner_account_id)
   limit 1;

  if found then
    if v_job.state = 'completed' then
      raise exception 'account_mutation_denied_deleted';
    end if;
    -- The recorded FACT first — it survives any state string, including `failed_retryable`.
    if v_job.irreversible_started_at is not null then
      raise exception 'account_mutation_denied_erasing';
    end if;
    if v_job.execution_cursor is not null
       and public.yorisou_account_deletion_stage_rank(v_job.execution_cursor)
           >= public.yorisou_account_deletion_irreversible_rank() then
      raise exception 'account_mutation_denied_erasing';
    end if;
    if v_job.state in ('locked','database_erasure','storage_erasure','identity_erasure','verifying') then
      raise exception 'account_mutation_denied_erasing';
    end if;
  end if;

  insert into public.yorisou_account_mutation_gates (owner_account_id)
  values (p_owner_account_id) on conflict (owner_account_id) do nothing;

  select * into v_gate from public.yorisou_account_mutation_gates
   where owner_account_id = p_owner_account_id for update;

  if v_gate.gate_state <> 'open' then
    raise exception 'account_mutation_denied_gate_%', v_gate.gate_state;
  end if;

  insert into public.yorisou_account_mutation_leases
    (owner_account_id, gate_generation, operation_code, request_nonce_hash, expires_at)
  values
    (p_owner_account_id, v_gate.generation, p_operation_code, left(coalesce(p_request_nonce_hash,''), 64),
     now() + make_interval(secs => p_ttl_seconds))
  returning id into v_lease;

  return jsonb_build_object('leaseId', v_lease, 'generation', v_gate.generation);
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_account_mutation_clock()
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare v_raw text; v_skew interval;
begin
  v_raw := current_setting('yorisou.deletion_clock_skew_seconds', true);
  if v_raw is null or v_raw = '' then return now(); end if;
  v_skew := make_interval(secs => least(greatest(v_raw::numeric, 0), 86400));
  return now() + v_skew;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_account_mutation_gate_finalize(p_owner_account_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_fingerprint text;
begin
  v_fingerprint := public.yorisou_account_deletion_fingerprint(p_owner_account_id);
  delete from public.yorisou_account_mutation_leases where owner_account_id = p_owner_account_id;
  update public.yorisou_account_mutation_gates
     set gate_state = 'completed',
         completed_at = now(),
         owner_fingerprint = v_fingerprint,
         owner_account_id = v_fingerprint,
         updated_at = now()
   where owner_account_id = p_owner_account_id;
  return found;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_assessment_result_delete(p_result_row_id uuid, p_owner_account_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_rows integer;
begin
  update public.yorisou_assessment_results
     set deleted_at = now(), dimension_output = '{}'::jsonb
   where id = p_result_row_id and owner_account_id = p_owner_account_id and deleted_at is null;
  get diagnostics v_rows = row_count;
  return v_rows > 0;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_assessment_result_erase(p_result_row_id uuid, p_owner_account_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_attempt uuid; v_rows integer;
begin
  select attempt_id into v_attempt from public.yorisou_assessment_results
   where id = p_result_row_id and owner_account_id = p_owner_account_id and deleted_at is null;
  if not found then return false; end if;

  -- Recommendation graph first, while the owner linkage still exists to authorize it.
  delete from public.yorisou_canonical_recommendation_actions where result_row_id = p_result_row_id;
  delete from public.yorisou_canonical_recommendation_items  where result_row_id = p_result_row_id;
  delete from public.yorisou_canonical_recommendation_sets   where result_row_id = p_result_row_id;

  -- Interpretation responses carry corrections, reasons and idempotency nonces.
  perform set_config('yorisou.erasure_context', p_result_row_id::text, true);
  delete from public.yorisou_interpretation_responses where result_row_id = p_result_row_id;
  perform set_config('yorisou.erasure_context', '', true);

  update public.yorisou_assessment_results
     set deleted_at            = now(),
         result_id             = null,
         original_result_id    = null,
         overlay_id            = null,
         dimension_output      = '{}'::jsonb,
         owner_account_id      = null,
         scoring_version       = null,
         result_schema_version = null
   where id = p_result_row_id;
  get diagnostics v_rows = row_count;

  update public.yorisou_assessment_attempts
     set answers = '{}'::jsonb, answered_count = 0, claim_token_hash = null,
         status = 'abandoned', completed_at = null, owner_account_id = null, claimed_at = null,
         expires_at = null, updated_at = now()
   where id = v_attempt;

  return v_rows > 0;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_attempt_claim(p_attempt_id uuid, p_claim_token_hash text, p_owner_account_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_attempt public.yorisou_assessment_attempts%rowtype;
        v_result uuid;
begin
  if p_owner_account_id is null or length(p_owner_account_id) = 0 then
    raise exception 'claim_owner_required';
  end if;

  select * into v_attempt from public.yorisou_assessment_attempts a
   where a.id = p_attempt_id for update;
  if not found then raise exception 'attempt_not_found'; end if;

  -- Already claimed by this same account -> idempotent success.
  if v_attempt.owner_account_id is not null then
    if v_attempt.owner_account_id = p_owner_account_id then
      select r.id into v_result from public.yorisou_assessment_results r where r.attempt_id = p_attempt_id;
      return v_result;
    end if;
    raise exception 'attempt_already_claimed_by_another_owner';
  end if;

  if v_attempt.claim_token_hash is null or v_attempt.claim_token_hash <> p_claim_token_hash then
    raise exception 'claim_token_invalid';
  end if;
  if v_attempt.expires_at is not null and v_attempt.expires_at < now() then
    raise exception 'claim_token_expired';
  end if;

  update public.yorisou_assessment_attempts
     set owner_account_id = p_owner_account_id,
         claimed_at       = now(),
         claim_token_hash = null,   -- single use
         expires_at       = null,   -- claimed attempts do not expire
         updated_at       = now()
   where id = p_attempt_id;

  update public.yorisou_assessment_results
     set owner_account_id = p_owner_account_id
   where attempt_id = p_attempt_id
  returning id into v_result;

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_attempt_complete(p_attempt_id uuid, p_claim_token_hash text, p_owner_account_id text, p_answers jsonb, p_answered_count integer, p_result_id text, p_overlay_id text, p_dimension_output jsonb, p_scoring_version text, p_result_schema_version text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_attempt public.yorisou_assessment_attempts%rowtype; v_existing uuid; v_result_row uuid;
begin
  -- CANONICAL ENVELOPE GUARD: exactly one key, exactly the approved version.
  if p_dimension_output is null
     or jsonb_typeof(p_dimension_output) <> 'object'
     or (select count(*) from jsonb_object_keys(p_dimension_output)) <> 1
     or p_dimension_output->>'v' is distinct from 'pds-v1' then
    raise exception 'assessment_persisted_envelope_invalid';
  end if;

  select * into v_attempt from public.yorisou_assessment_attempts a
   where a.id = p_attempt_id
     and (
       (a.owner_account_id is null and a.claim_token_hash is not null and a.claim_token_hash = p_claim_token_hash)
       or (a.owner_account_id is not null and a.owner_account_id = p_owner_account_id)
     )
   for update;
  if not found then raise exception 'attempt_not_found_or_not_writable'; end if;

  select r.id into v_existing from public.yorisou_assessment_results r where r.attempt_id = p_attempt_id;
  if v_existing is not null then return v_existing; end if;

  if v_attempt.owner_account_id is null
     and v_attempt.expires_at is not null and v_attempt.expires_at <= now() then
    raise exception 'attempt_expired';
  end if;
  if p_answered_count < v_attempt.required_count then raise exception 'attempt_incomplete_coverage'; end if;

  update public.yorisou_assessment_attempts
     set answers = p_answers, answered_count = p_answered_count,
         status = 'completed', completed_at = now(), updated_at = now()
   where id = p_attempt_id;

  insert into public.yorisou_assessment_results
    (attempt_id, owner_account_id, method_id, method_version, scoring_version,
     result_schema_version, result_id, overlay_id, dimension_output, original_result_id)
  values
    (p_attempt_id, v_attempt.owner_account_id, v_attempt.method_id, v_attempt.method_version,
     p_scoring_version, p_result_schema_version, p_result_id, p_overlay_id,
     p_dimension_output, p_result_id)
  returning id into v_result_row;
  return v_result_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_attempt_save_progress(p_attempt_id uuid, p_claim_token_hash text, p_owner_account_id text, p_answers jsonb, p_answered_count integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_rows integer;
begin
  update public.yorisou_assessment_attempts a
     set answers = p_answers, answered_count = p_answered_count, updated_at = now()
   where a.id = p_attempt_id
     and a.status = 'in_progress'
     and (
       (a.owner_account_id is null and a.claim_token_hash is not null
        and a.claim_token_hash = p_claim_token_hash
        and (a.expires_at is null or a.expires_at > now()))   -- expiry enforced here
       or (a.owner_account_id is not null and a.owner_account_id = p_owner_account_id)
     );
  get diagnostics v_rows = row_count;
  if v_rows = 0 then
    -- Distinguish expiry so the UI can explain it rather than showing a generic failure.
    if exists (select 1 from public.yorisou_assessment_attempts a
                where a.id = p_attempt_id and a.owner_account_id is null
                  and a.expires_at is not null and a.expires_at <= now()) then
      raise exception 'attempt_expired';
    end if;
    raise exception 'attempt_not_found_or_not_writable';
  end if;
  return p_answered_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_attempt_start(p_method_id text, p_method_version text, p_required_count integer, p_claim_token_hash text, p_entry_source text DEFAULT NULL::text, p_ttl_hours integer DEFAULT 72)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if p_claim_token_hash is null or length(p_claim_token_hash) < 32 then
    raise exception 'attempt_claim_token_required';
  end if;
  insert into public.yorisou_assessment_attempts
    (method_id, method_version, required_count, claim_token_hash, entry_source, expires_at)
  values
    (p_method_id, p_method_version, p_required_count, p_claim_token_hash, p_entry_source,
     now() + make_interval(hours => greatest(0, coalesce(p_ttl_hours, 72))))
  returning id into v_id;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_canonical_recommendation_act(p_item_id uuid, p_owner_account_id text, p_action text, p_source_surface text, p_intent_nonce uuid DEFAULT NULL::uuid, p_result_row_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_item public.yorisou_canonical_recommendation_items%rowtype;
        v_set public.yorisou_canonical_recommendation_sets%rowtype;
        v_existing public.yorisou_canonical_recommendation_actions%rowtype; v_id uuid;
begin
  select * into v_item from public.yorisou_canonical_recommendation_items
   where id = p_item_id and owner_account_id = p_owner_account_id;
  if not found then raise exception 'recommendation_item_not_found'; end if;

  select * into v_set from public.yorisou_canonical_recommendation_sets
   where id = v_item.set_id and owner_account_id = p_owner_account_id;
  if not found then raise exception 'recommendation_item_not_found'; end if;

  if p_result_row_id is not null then
    if v_item.result_row_id is distinct from p_result_row_id
       or v_set.result_row_id is distinct from p_result_row_id then
      raise exception 'recommendation_item_not_found';   -- concealed
    end if;
  end if;

  perform public.yorisou_canonical_recommendation_eligibility(v_item.result_row_id, p_owner_account_id);

  if p_intent_nonce is not null then
    select * into v_existing from public.yorisou_canonical_recommendation_actions
     where item_id = p_item_id and owner_account_id = p_owner_account_id
       and intent_nonce = p_intent_nonce;
    if found then
      -- A replay must be a replay of the SAME request. Returning the stored row for a different
      -- action would tell the caller their new choice succeeded when it was never recorded.
      if v_existing.action        is distinct from p_action
         or v_existing.source_surface is distinct from p_source_surface
         or v_existing.result_row_id  is distinct from v_item.result_row_id then
        raise exception 'recommendation_action_intent_conflict';
      end if;
      return v_existing.id;
    end if;
  end if;

  begin
    insert into public.yorisou_canonical_recommendation_actions
      (item_id, set_id, result_row_id, owner_account_id, action, source_surface, intent_nonce)
    values
      (p_item_id, v_item.set_id, v_item.result_row_id, p_owner_account_id, p_action,
       p_source_surface, p_intent_nonce)
    returning id into v_id;
  exception when unique_violation then
    -- Concurrent same-nonce request won. Re-read and apply the SAME comparison: a concurrent
    -- conflicting payload must not be absorbed just because it lost the race.
    select * into v_existing from public.yorisou_canonical_recommendation_actions
     where item_id = p_item_id and owner_account_id = p_owner_account_id
       and intent_nonce = p_intent_nonce;
    if not found then raise; end if;
    if v_existing.action        is distinct from p_action
       or v_existing.source_surface is distinct from p_source_surface
       or v_existing.result_row_id  is distinct from v_item.result_row_id then
      raise exception 'recommendation_action_intent_conflict';
    end if;
    return v_existing.id;
  end;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_canonical_recommendation_eligibility(p_result_row_id uuid, p_owner_account_id text)
 RETURNS TABLE(accepted_result_id text, original_result_id text, basis text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_res public.yorisou_assessment_results%rowtype; v_resp public.yorisou_interpretation_responses%rowtype;
begin
  select * into v_res from public.yorisou_assessment_results
   where id = p_result_row_id and owner_account_id = p_owner_account_id and deleted_at is null;
  if not found then raise exception 'result_not_found'; end if;

  if v_res.dimension_output is null
     or (select count(*) from jsonb_object_keys(v_res.dimension_output)) <> 1
     or v_res.dimension_output->>'v' is distinct from 'pds-v1' then
    raise exception 'result_envelope_invalid';
  end if;

  select * into v_resp from public.yorisou_interpretation_responses
   where result_row_id = p_result_row_id order by sequence_no desc limit 1;
  if not found then raise exception 'recommendation_not_permitted'; end if;
  if v_resp.response_type not in ('confirmed','corrected') then raise exception 'recommendation_not_permitted'; end if;
  if v_resp.recommendation_use_permitted is not true then raise exception 'recommendation_not_permitted'; end if;

  accepted_result_id := case when v_resp.response_type = 'corrected'
                             then v_resp.corrected_result_id else v_res.result_id end;
  if accepted_result_id is null then raise exception 'recommendation_not_permitted'; end if;
  original_result_id := v_res.original_result_id;
  basis := v_resp.response_type;
  return next;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_canonical_recommendation_materialize(p_result_row_id uuid, p_owner_account_id text, p_content_version text, p_source_surface text, p_items jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_e record; v_set uuid; v_item jsonb; v_rank integer := 0;
begin
  select * into v_e from public.yorisou_canonical_recommendation_eligibility(p_result_row_id, p_owner_account_id);

  select id into v_set from public.yorisou_canonical_recommendation_sets
   where result_row_id = p_result_row_id and owner_account_id = p_owner_account_id
     and accepted_result_id = v_e.accepted_result_id and content_version = p_content_version
     and lifecycle_state = 'active'
   order by generated_at desc limit 1;
  if v_set is not null then return v_set; end if;

  -- A change of accepted result supersedes earlier sets rather than deleting them: what was
  -- recommended under a previous self-understanding is part of the person's history.
  update public.yorisou_canonical_recommendation_sets set lifecycle_state = 'superseded'
   where result_row_id = p_result_row_id and owner_account_id = p_owner_account_id
     and lifecycle_state = 'active';

  insert into public.yorisou_canonical_recommendation_sets
    (result_row_id, owner_account_id, accepted_result_id, original_result_id,
     eligibility_basis, content_version, source_surface)
  values
    (p_result_row_id, p_owner_account_id, v_e.accepted_result_id, v_e.original_result_id,
     v_e.basis, p_content_version, p_source_surface)
  returning id into v_set;

  if jsonb_typeof(p_items) <> 'array' then raise exception 'recommendation_items_invalid'; end if;
  if jsonb_array_length(p_items) > 5 then raise exception 'recommendation_items_too_many'; end if;

  for v_item in select * from jsonb_array_elements(p_items) loop
    v_rank := v_rank + 1;
    insert into public.yorisou_canonical_recommendation_items
      (set_id, owner_account_id, result_row_id, rank, recommendation_key, object_type,
       source_class, commercial_status, reason_code, limitations_code)
    values
      (v_set, p_owner_account_id, p_result_row_id, v_rank,
       v_item->>'recommendationKey', v_item->>'objectType', v_item->>'sourceClass',
       coalesce(v_item->>'commercialStatus','none'), v_item->>'reasonCode', v_item->>'limitationsCode');
  end loop;

  return v_set;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_daily_record_correct(p_owner_account_id text, p_entry_local_date date, p_produced_at timestamp with time zone, p_state jsonb, p_memo text, p_ack_id text, p_reason_code text DEFAULT 'user_correction'::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_record public.yorisou_daily_state_records%rowtype;
  v_next integer;
begin
  if p_reason_code <> 'user_correction' then
    raise exception 'daily_record_invalid_reason';
  end if;
  select * into v_record from public.yorisou_daily_state_records
  where owner_account_id = p_owner_account_id
    and entry_local_date = p_entry_local_date
  for update;
  if not found then
    raise exception 'daily_record_not_found';
  end if;
  if (timezone(v_record.timezone, now()))::date <> v_record.entry_local_date then
    raise exception 'daily_record_correction_window_closed';
  end if;
  v_next := v_record.current_version + 1;
  insert into public.yorisou_daily_state_record_versions
    (record_id, version, produced_at, state, memo, ack_id, reason_code)
  values (v_record.id, v_next, coalesce(p_produced_at, now()), p_state, p_memo, p_ack_id, 'user_correction');
  update public.yorisou_daily_state_records
  set state = p_state,
      memo = p_memo,
      ack_id = p_ack_id,
      current_version = v_next,
      updated_at = now()
  where id = v_record.id;
  insert into public.yorisou_daily_state_history_events
    (record_id, owner_account_id, event_type, version, reason_code)
  values (v_record.id, p_owner_account_id, 'corrected', v_next, 'user_correction');
  return v_next;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_daily_record_create(p_owner_account_id text, p_method_version text, p_schema_version text, p_ack_version text, p_produced_at timestamp with time zone, p_entry_local_date date, p_timezone text, p_utc_offset_minutes integer, p_state jsonb, p_memo text, p_ack_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_record_id uuid;
begin
  if p_owner_account_id is null or length(p_owner_account_id) = 0 then
    raise exception 'daily_record_owner_required';
  end if;
  if exists (
    select 1 from public.yorisou_daily_state_records
    where owner_account_id = p_owner_account_id
      and entry_local_date = p_entry_local_date
  ) then
    raise exception 'daily_record_exists';
  end if;
  insert into public.yorisou_daily_state_records
    (owner_account_id, method_version, schema_version, ack_version, produced_at,
     entry_local_date, timezone, utc_offset_minutes, state, memo, ack_id, current_version)
  values
    (p_owner_account_id, p_method_version, p_schema_version, p_ack_version, p_produced_at,
     p_entry_local_date, p_timezone, p_utc_offset_minutes, p_state, p_memo, p_ack_id, 1)
  returning id into v_record_id;
  insert into public.yorisou_daily_state_record_versions
    (record_id, version, produced_at, state, memo, ack_id, reason_code)
  values (v_record_id, 1, p_produced_at, p_state, p_memo, p_ack_id, 'initial');
  insert into public.yorisou_daily_state_history_events
    (record_id, owner_account_id, event_type, version, reason_code)
  values (v_record_id, p_owner_account_id, 'created', 1, 'initial');
  return v_record_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_daily_record_delete(p_owner_account_id text, p_entry_local_date date, p_deleted_by text DEFAULT 'owner'::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_record public.yorisou_daily_state_records%rowtype;
begin
  select * into v_record from public.yorisou_daily_state_records
  where owner_account_id = p_owner_account_id
    and entry_local_date = p_entry_local_date
  for update;
  if not found then
    return false;
  end if;
  -- Transaction-local governed-erase flag: the ONLY context that may delete
  -- content or audit rows.
  perform set_config('yorisou.dci_governed_erase', 'on', true);
  delete from public.yorisou_daily_state_record_versions where record_id = v_record.id;
  delete from public.yorisou_daily_state_records where id = v_record.id;
  delete from public.yorisou_daily_state_history_events where record_id = v_record.id;
  perform set_config('yorisou.dci_governed_erase', 'off', true);
  insert into public.yorisou_daily_state_history_events
    (record_id, owner_account_id, event_type, version, reason_code, retention_expires_at)
  values (v_record.id, p_owner_account_id, 'deleted', v_record.current_version, 'user_deleted', now() + interval '12 months');
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_daily_tombstone_purge_expired(p_limit integer DEFAULT 500)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_deleted integer;
begin
  if p_limit is null or p_limit < 1 or p_limit > 5000 then
    raise exception 'daily_purge_invalid_limit';
  end if;
  perform set_config('yorisou.dci_governed_erase', 'on', true);
  with expired as (
    select id from public.yorisou_daily_state_history_events
    where event_type = 'deleted'
      and retention_expires_at is not null
      and retention_expires_at <= now()
    order by retention_expires_at
    limit p_limit
    for update
  )
  delete from public.yorisou_daily_state_history_events e
  using expired
  where e.id = expired.id;
  get diagnostics v_deleted = row_count;
  perform set_config('yorisou.dci_governed_erase', 'off', true);
  return v_deleted;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_dci_block_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'DELETE' and current_setting('yorisou.dci_governed_erase', true) = 'on' then
    return old;
  end if;
  raise exception 'append_only: % on % is not permitted', tg_op, tg_table_name;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_identity_links_erase(p_owner_account_id text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_erased integer := 0;
begin
  if p_owner_account_id is null or char_length(p_owner_account_id) = 0 then
    raise exception 'identity_link_owner_required';
  end if;

  perform 1 from public.yorisou_canonical_identity_links
   where owner_account_id = p_owner_account_id for update;

  update public.yorisou_canonical_identity_links
     set link_state = 'erased', owner_account_id = null, link_digest = null,
         erased_at = coalesce(erased_at, now()), updated_at = now()
   where owner_account_id = p_owner_account_id and link_state = 'active';
  get diagnostics v_erased = row_count;

  return v_erased;
end $function$

CREATE OR REPLACE FUNCTION public.yorisou_identity_links_retire(p_owner_account_id text, p_link_kind text, p_link_digest text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_owner   text;
  v_retired integer := 0;
begin
  if p_owner_account_id is null or char_length(p_owner_account_id) = 0 then
    raise exception 'identity_link_owner_required';
  end if;
  if p_link_kind is null or p_link_digest is null then
    raise exception 'identity_link_entry_requires_kind_and_digest';
  end if;

  select owner_account_id into v_owner
    from public.yorisou_canonical_identity_links
   where link_kind = p_link_kind and link_digest = p_link_digest and link_state = 'active'
   for update;

  if v_owner is null then return 0; end if;          -- already retired, or never held
  if v_owner <> p_owner_account_id then
    raise exception 'identity_link_conflict:%', p_link_kind;
  end if;

  update public.yorisou_canonical_identity_links
     set link_state = 'erased', owner_account_id = null, link_digest = null,
         erased_at = now(), updated_at = now()
   where link_kind = p_link_kind and link_digest = p_link_digest
     and link_state = 'active' and owner_account_id = p_owner_account_id;
  get diagnostics v_retired = row_count;
  return v_retired;
end $function$

CREATE OR REPLACE FUNCTION public.yorisou_identity_links_sync(p_owner_account_id text, p_owner_fingerprint text, p_links jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_link       jsonb;
  v_kind       text;
  v_digest     text;
  v_other      text;
  v_added      integer := 0;
  v_unchanged  integer := 0;
begin
  if p_owner_account_id is null or char_length(p_owner_account_id) = 0 then
    raise exception 'identity_link_owner_required';
  end if;
  if p_owner_fingerprint is null or p_owner_fingerprint !~ '^[0-9a-f]{64}$' then
    raise exception 'identity_link_owner_fingerprint_must_be_sha256_hex';
  end if;
  if p_links is null or jsonb_typeof(p_links) <> 'array' then
    raise exception 'identity_link_set_must_be_array';
  end if;

  perform 1 from public.yorisou_canonical_identity_links
   where owner_account_id = p_owner_account_id and link_state = 'active'
   for update;

  -- Validate the whole set BEFORE writing any of it. A partially applied identity set is a state no
  -- reader has a name for.
  for v_link in select * from jsonb_array_elements(p_links) loop
    v_kind   := v_link->>'kind';
    v_digest := v_link->>'digest';
    if v_kind is null or v_digest is null then
      raise exception 'identity_link_entry_requires_kind_and_digest';
    end if;
    if v_kind not in ('email','line_subject','user_profile','auth_identity','provisioning') then
      raise exception 'identity_link_kind_unknown:%', v_kind;
    end if;
    if v_kind in ('email','line_subject') and v_digest !~ '^[0-9a-f]{64}$' then
      raise exception 'identity_link_digest_must_be_sha256_hex:%', v_kind;
    end if;

    select owner_account_id into v_other
      from public.yorisou_canonical_identity_links
     where link_kind = v_kind and link_digest = v_digest and link_state = 'active'
     for update;
    if v_other is not null and v_other <> p_owner_account_id then
      raise exception 'identity_link_conflict:%', v_kind;
    end if;
  end loop;

  -- NO RETIREMENT HERE. Deliberately. See the header: the caller's link set comes from a read that
  -- can be stale, and retiring on absence lets that stale read destroy a true record.
  for v_link in select * from jsonb_array_elements(p_links) loop
    v_kind   := v_link->>'kind';
    v_digest := v_link->>'digest';
    if exists (
      select 1 from public.yorisou_canonical_identity_links
       where link_kind = v_kind and link_digest = v_digest
         and link_state = 'active' and owner_account_id = p_owner_account_id
    ) then
      v_unchanged := v_unchanged + 1;
      continue;
    end if;
    begin
      insert into public.yorisou_canonical_identity_links
        (owner_account_id, owner_fingerprint, link_kind, link_digest)
      values (p_owner_account_id, p_owner_fingerprint, v_kind, v_digest);
      v_added := v_added + 1;
    exception when unique_violation then
      select owner_account_id into v_other
        from public.yorisou_canonical_identity_links
       where link_kind = v_kind and link_digest = v_digest and link_state = 'active';
      if v_other is distinct from p_owner_account_id then
        raise exception 'identity_link_conflict:%', v_kind;
      end if;
      v_unchanged := v_unchanged + 1;
    end;
  end loop;

  return jsonb_build_object(
    'added', v_added, 'retired', 0, 'unchanged', v_unchanged,
    'active', (select count(*) from public.yorisou_canonical_identity_links
                where owner_account_id = p_owner_account_id and link_state = 'active')
  );
end $function$

CREATE OR REPLACE FUNCTION public.yorisou_interpretation_respond(p_result_row_id uuid, p_owner_account_id text, p_response_type text, p_corrected_result_id text DEFAULT NULL::text, p_reason_code text DEFAULT NULL::text, p_source text DEFAULT 'web'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_owner text; v_deleted timestamptz; v_prev uuid; v_id uuid; v_permit boolean;
begin
  select r.owner_account_id, r.deleted_at into v_owner, v_deleted
    from public.yorisou_assessment_results r where r.id = p_result_row_id;
  if not found then raise exception 'result_not_found'; end if;
  -- An erased result can never receive new responses.
  if v_deleted is not null then raise exception 'result_erased'; end if;
  if v_owner is null or v_owner <> p_owner_account_id then raise exception 'result_not_owned'; end if;

  select id into v_prev from public.yorisou_interpretation_responses
   where result_row_id = p_result_row_id order by created_at desc limit 1;

  -- ONLY an explicit confirmation or correction permits downstream use.
  -- rejected AND deferred both withhold it; silence never grants it.
  v_permit := p_response_type in ('confirmed','corrected');

  insert into public.yorisou_interpretation_responses
    (result_row_id, owner_account_id, response_type, corrected_result_id, reason_code,
     supersedes_response_id, recommendation_use_permitted, continuity_use_permitted, source)
  values
    (p_result_row_id, p_owner_account_id, p_response_type, p_corrected_result_id, p_reason_code,
     v_prev, v_permit, v_permit, p_source)
  returning id into v_id;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_interpretation_respond(p_result_row_id uuid, p_owner_account_id text, p_response_type text, p_corrected_result_id text DEFAULT NULL::text, p_reason_code text DEFAULT NULL::text, p_source text DEFAULT 'web'::text, p_intent_nonce uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_owner text; v_deleted timestamptz; v_prev uuid; v_id uuid; v_permit boolean;
        v_existing public.yorisou_interpretation_responses%rowtype;
begin
  select r.owner_account_id, r.deleted_at into v_owner, v_deleted
    from public.yorisou_assessment_results r where r.id = p_result_row_id;
  if not found then raise exception 'result_not_found'; end if;
  if v_deleted is not null then raise exception 'result_erased'; end if;
  if v_owner is null or v_owner <> p_owner_account_id then raise exception 'result_not_owned'; end if;

  if p_intent_nonce is not null then
    select * into v_existing from public.yorisou_interpretation_responses
     where result_row_id = p_result_row_id
       and owner_account_id = p_owner_account_id
       and intent_nonce = p_intent_nonce;
    if found then
      if v_existing.response_type      is distinct from p_response_type
         or v_existing.corrected_result_id is distinct from p_corrected_result_id
         or v_existing.reason_code     is distinct from p_reason_code
         or v_existing.source          is distinct from p_source then
        raise exception 'interpretation_intent_conflict';
      end if;
      return v_existing.id;
    end if;
  end if;

  select id into v_prev from public.yorisou_interpretation_responses
   where result_row_id = p_result_row_id order by sequence_no desc limit 1;

  v_permit := p_response_type in ('confirmed','corrected');

  begin
    insert into public.yorisou_interpretation_responses
      (result_row_id, owner_account_id, response_type, corrected_result_id, reason_code,
       supersedes_response_id, recommendation_use_permitted, continuity_use_permitted, source,
       intent_nonce)
    values
      (p_result_row_id, p_owner_account_id, p_response_type, p_corrected_result_id, p_reason_code,
       v_prev, v_permit, v_permit, p_source, p_intent_nonce)
    returning id into v_id;
  exception when unique_violation then
    select * into v_existing from public.yorisou_interpretation_responses
     where result_row_id = p_result_row_id
       and owner_account_id = p_owner_account_id
       and intent_nonce = p_intent_nonce;
    if not found then raise; end if;
    if v_existing.response_type      is distinct from p_response_type
       or v_existing.corrected_result_id is distinct from p_corrected_result_id
       or v_existing.reason_code     is distinct from p_reason_code
       or v_existing.source          is distinct from p_source then
      raise exception 'interpretation_intent_conflict';
    end if;
    return v_existing.id;
  end;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_interpretation_supersedes_same_result()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare v_other uuid;
begin
  if new.supersedes_response_id is null then return new; end if;
  select result_row_id into v_other from public.yorisou_interpretation_responses
   where id = new.supersedes_response_id;
  if v_other is null or v_other <> new.result_row_id then
    raise exception 'response_supersession_cross_result';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_line_event_record(p_line_event_id text, p_line_subject_hash text, p_event_type text, p_line_subject_id text DEFAULT NULL::text, p_webhook_event_id text DEFAULT NULL::text, p_owner_account_id text DEFAULT NULL::text, p_owner_fingerprint text DEFAULT NULL::text, p_source_type text DEFAULT NULL::text, p_message_type text DEFAULT NULL::text, p_message_text text DEFAULT NULL::text, p_postback_data text DEFAULT NULL::text, p_delivery_mode text DEFAULT NULL::text, p_is_redelivery boolean DEFAULT false, p_reply_token_present boolean DEFAULT false, p_reply_status text DEFAULT 'not_attempted'::text, p_reply_error text DEFAULT NULL::text, p_event_timestamp timestamp with time zone DEFAULT NULL::timestamp with time zone, p_received_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_subject  public.yorisou_canonical_line_subjects%rowtype;
  v_existing public.yorisou_canonical_line_events%rowtype;
  v_received timestamptz := coalesce(p_received_at, now());
begin
  if p_line_event_id is null or length(trim(p_line_event_id)) = 0 then
    raise exception 'line_event_id_required';
  end if;
  if p_line_subject_hash is null or p_line_subject_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'line_subject_hash_must_be_sha256_hex';
  end if;

  -- THE BARRIER. Locking the subject before touching any event row is what serializes a brand-new
  -- event id against a completed erasure. Without it the two transactions never contend, because
  -- they address different rows, and both succeed.
  v_subject := public.yorisou_line_subject_lock(p_line_subject_hash, p_owner_fingerprint);

  if v_subject.state = 'erased' then
    -- Absorbed. No row, no raw subject id, no message text, no postback data, no reply error.
    return jsonb_build_object('outcome', 'erased', 'line_event_id', p_line_event_id);
  end if;

  select * into v_existing
    from public.yorisou_canonical_line_events
   where line_event_id = p_line_event_id
     for update;

  if not found and p_webhook_event_id is not null then
    select * into v_existing
      from public.yorisou_canonical_line_events
     where webhook_event_id = p_webhook_event_id
       for update;
  end if;

  if found then
    if v_existing.line_subject_hash is distinct from p_line_subject_hash then
      raise exception 'line_event_identity_conflict';
    end if;

    if v_existing.retention_state = 'erased' then
      return jsonb_build_object('outcome', 'erased', 'line_event_id', v_existing.line_event_id);
    end if;

    update public.yorisou_canonical_line_events
       set reply_status        = coalesce(p_reply_status, reply_status),
           reply_error         = p_reply_error,
           reply_token_present = coalesce(p_reply_token_present, reply_token_present),
           message_text        = coalesce(p_message_text, message_text),
           is_redelivery       = is_redelivery or coalesce(p_is_redelivery, false),
           owner_account_id    = coalesce(p_owner_account_id, owner_account_id),
           owner_fingerprint   = coalesce(p_owner_fingerprint, owner_fingerprint),
           line_subject_id     = coalesce(p_line_subject_id, line_subject_id),
           updated_at          = now()
     where line_event_id = v_existing.line_event_id;

    if p_owner_fingerprint is not null and v_subject.owner_fingerprint is distinct from p_owner_fingerprint then
      update public.yorisou_canonical_line_subjects
         set owner_fingerprint = p_owner_fingerprint, updated_at = now()
       where line_subject_hash = p_line_subject_hash;
    end if;

    return jsonb_build_object('outcome', 'repeated', 'line_event_id', v_existing.line_event_id);
  end if;

  -- The handler is scoped to the INSERT alone rather than to the whole function. A plpgsql exception
  -- block is a subtransaction, and rolling the whole body back would also roll back the subject row
  -- this transaction may have just created — discarding the barrier's state to report a duplicate.
  begin
    insert into public.yorisou_canonical_line_events (
      line_event_id, webhook_event_id, line_subject_hash, line_subject_id, owner_account_id, owner_fingerprint,
      source_type, event_type, message_type, message_text, postback_data, delivery_mode,
      is_redelivery, reply_token_present, reply_status, reply_error, event_timestamp, received_at
    ) values (
      p_line_event_id, p_webhook_event_id, p_line_subject_hash, p_line_subject_id, p_owner_account_id, p_owner_fingerprint,
      p_source_type, p_event_type, p_message_type, p_message_text, p_postback_data, p_delivery_mode,
      coalesce(p_is_redelivery, false), coalesce(p_reply_token_present, false),
      coalesce(p_reply_status, 'not_attempted'), p_reply_error, p_event_timestamp, v_received
    );
  exception
    when unique_violation then
      -- Lost the insert race on `webhook_event_id`. The winner wrote the same event, so this is a
      -- repeat, not a failure — but only if it is genuinely the same subject.
      if exists (
        select 1 from public.yorisou_canonical_line_events
         where webhook_event_id = p_webhook_event_id
           and line_subject_hash is distinct from p_line_subject_hash
      ) then
        raise exception 'line_event_identity_conflict';
      end if;
      return jsonb_build_object('outcome', 'repeated', 'line_event_id', p_line_event_id);
  end;

  if p_owner_fingerprint is not null and v_subject.owner_fingerprint is distinct from p_owner_fingerprint then
    update public.yorisou_canonical_line_subjects
       set owner_fingerprint = p_owner_fingerprint, updated_at = now()
     where line_subject_hash = p_line_subject_hash;
  end if;

  return jsonb_build_object('outcome', 'recorded', 'line_event_id', p_line_event_id);
end $function$

CREATE OR REPLACE FUNCTION public.yorisou_line_subject_erase(p_line_subject_hash text, p_owner_fingerprint text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_subject   public.yorisou_canonical_line_subjects%rowtype;
  v_erased    int;
  v_residue   int;
  v_already   boolean;
begin
  v_subject := public.yorisou_line_subject_lock(p_line_subject_hash, p_owner_fingerprint);
  v_already := v_subject.state = 'erased';

  update public.yorisou_canonical_line_subjects
     set state             = 'erased',
         erased_at         = coalesce(erased_at, now()),
         owner_fingerprint = coalesce(p_owner_fingerprint, owner_fingerprint),
         updated_at        = now()
   where line_subject_hash = p_line_subject_hash;

  update public.yorisou_canonical_line_events
     set retention_state   = 'erased',
         erased_at         = now(),
         message_text      = null,
         postback_data     = null,
         reply_error       = null,
         owner_account_id  = null,
         line_subject_id   = null,
         owner_fingerprint = coalesce(p_owner_fingerprint, owner_fingerprint),
         updated_at        = now()
   where line_subject_hash = p_line_subject_hash
     and retention_state = 'active';

  get diagnostics v_erased = row_count;

  select count(*)::int into v_residue
    from public.yorisou_canonical_line_events
   where line_subject_hash = p_line_subject_hash
     and retention_state = 'active';

  if v_residue <> 0 then
    -- Unreachable under the subject lock; asserted because a deletion that reports success over
    -- residue is the one failure mode this whole family exists to prevent.
    raise exception 'line_subject_erasure_residue';
  end if;

  return jsonb_build_object(
    'subject_state', 'erased',
    'events_erased', v_erased,
    'active_residue', 0,
    'already_erased', v_already
  );
end $function$

CREATE OR REPLACE FUNCTION public.yorisou_line_subject_lock(p_line_subject_hash text, p_owner_fingerprint text DEFAULT NULL::text)
 RETURNS yorisou_canonical_line_subjects
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_subject public.yorisou_canonical_line_subjects%rowtype;
begin
  if p_line_subject_hash is null or p_line_subject_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'line_subject_hash_must_be_sha256_hex';
  end if;

  for i in 1..2 loop
    select * into v_subject
      from public.yorisou_canonical_line_subjects
     where line_subject_hash = p_line_subject_hash
       for update;
    if found then
      return v_subject;
    end if;

    begin
      insert into public.yorisou_canonical_line_subjects (line_subject_hash, owner_fingerprint)
      values (p_line_subject_hash, p_owner_fingerprint);
    exception when unique_violation then
      -- A concurrent inserter won. Loop once more; the select will now find and LOCK its row, which
      -- is what makes the two callers serial instead of both proceeding on an unlocked subject.
      null;
    end;
  end loop;

  select * into v_subject
    from public.yorisou_canonical_line_subjects
   where line_subject_hash = p_line_subject_hash
     for update;
  if not found then
    raise exception 'line_subject_state_unavailable';
  end if;
  return v_subject;
end $function$

CREATE OR REPLACE FUNCTION public.yorisou_provisioning_abandon(p_provisioning_key text, p_token_hash text, p_generation integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_saga public.yorisou_identity_provisioning_sagas%rowtype; v_rows int;
begin
  select * into v_saga from public.yorisou_identity_provisioning_sagas
   where provisioning_key = p_provisioning_key for update;
  if not found then return false; end if;
  if v_saga.account_id is not null then
    raise exception 'provisioning_abandon_refused_account_bound';
  end if;
  if v_saga.executor_token_hash is distinct from p_token_hash
     or v_saga.executor_generation is distinct from p_generation then
    raise exception 'provisioning_executor_mismatch';
  end if;

  delete from public.yorisou_identity_provisioning_sagas
   where provisioning_key = p_provisioning_key and account_id is null;
  get diagnostics v_rows = row_count;
  return v_rows > 0;
end $function$

CREATE OR REPLACE FUNCTION public.yorisou_provisioning_complete_step(p_provisioning_key text, p_token_hash text, p_generation integer, p_expected_cursor text, p_next_cursor text, p_account_id text DEFAULT NULL::text, p_owner_fingerprint text DEFAULT NULL::text, p_session_fingerprint text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_saga public.yorisou_identity_provisioning_sagas%rowtype;
  v_next_state text;
begin
  select * into v_saga from public.yorisou_identity_provisioning_sagas
   where provisioning_key = p_provisioning_key for update;
  if not found then raise exception 'provisioning_saga_not_found'; end if;

  if v_saga.state in ('completed','failed_terminal') then
    raise exception 'provisioning_terminal_%', v_saga.state;
  end if;
  if v_saga.executor_token_hash is distinct from p_token_hash then
    raise exception 'provisioning_executor_mismatch';
  end if;
  if v_saga.executor_generation is distinct from p_generation then
    raise exception 'provisioning_executor_generation_stale';
  end if;
  if v_saga.provisioning_cursor is distinct from p_expected_cursor then
    raise exception 'provisioning_cursor_mismatch';
  end if;
  if public.yorisou_provisioning_stage_rank(p_next_cursor)
     is distinct from public.yorisou_provisioning_stage_rank(p_expected_cursor) + 1 then
    raise exception 'provisioning_cursor_illegal_transition';
  end if;

  -- The account binding is written once and is then immutable. A saga that changed which account it
  -- belonged to could bind a session to one account and complete another.
  if p_account_id is not null and v_saga.account_id is not null
     and v_saga.account_id is distinct from p_account_id then
    raise exception 'provisioning_account_rebind_refused';
  end if;

  v_next_state := public.yorisou_provisioning_state_for_cursor(p_next_cursor);

  update public.yorisou_identity_provisioning_sagas
     set provisioning_cursor = p_next_cursor,
         state               = v_next_state,
         account_id          = coalesce(v_saga.account_id, p_account_id),
         owner_fingerprint   = coalesce(v_saga.owner_fingerprint, p_owner_fingerprint),
         session_fingerprint = coalesce(p_session_fingerprint, v_saga.session_fingerprint),
         failure_class       = null,
         last_error_code     = null,
         completed_at        = case when v_next_state = 'completed' then now() else v_saga.completed_at end,
         updated_at          = now()
   where provisioning_key = p_provisioning_key;

  return jsonb_build_object(
    'cursor', p_next_cursor, 'state', v_next_state,
    'accountId', coalesce(v_saga.account_id, p_account_id)
  );
end $function$

CREATE OR REPLACE FUNCTION public.yorisou_provisioning_open(p_provisioning_key text, p_token_hash text, p_ttl_seconds integer DEFAULT 90)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_saga   public.yorisou_identity_provisioning_sagas%rowtype;
  v_locked boolean := false;
begin
  if p_provisioning_key is null or p_provisioning_key !~ '^[0-9a-f]{64}$' then
    raise exception 'provisioning_key_must_be_sha256_hex';
  end if;
  if p_token_hash is null or char_length(p_token_hash) < 32 then
    raise exception 'provisioning_executor_token_required';
  end if;
  if p_ttl_seconds is null or p_ttl_seconds < 5 or p_ttl_seconds > 600 then
    raise exception 'provisioning_executor_ttl_out_of_range';
  end if;

  -- Lock-or-create. The re-select after a lost insert race is not optional: `on conflict` returns no
  -- row, and proceeding without the lock is how two requests both believe they opened the saga.
  for i in 1..2 loop
    select * into v_saga from public.yorisou_identity_provisioning_sagas
     where provisioning_key = p_provisioning_key for update;
    if found then v_locked := true; exit; end if;
    begin
      insert into public.yorisou_identity_provisioning_sagas (provisioning_key) values (p_provisioning_key);
    exception when unique_violation then
      null;  -- a concurrent opener won; loop once more and LOCK its row
    end;
  end loop;
  if not v_locked then raise exception 'provisioning_saga_unavailable'; end if;

  -- Already done. A retry of a registration that succeeded is not a second registration; it is the
  -- same one, and it is finished. This is what makes "the response was lost" resolvable.
  if v_saga.state = 'completed' then
    return jsonb_build_object(
      'outcome', 'completed', 'claimed', false,
      'cursor', v_saga.provisioning_cursor, 'state', v_saga.state,
      'generation', v_saga.executor_generation, 'accountId', v_saga.account_id
    );
  end if;

  if v_saga.state = 'failed_terminal' then
    return jsonb_build_object(
      'outcome', 'failed_terminal', 'claimed', false,
      'cursor', v_saga.provisioning_cursor, 'state', v_saga.state,
      'failureClass', v_saga.failure_class, 'accountId', v_saga.account_id
    );
  end if;

  -- Someone else is driving and their claim has not lapsed. Two concurrent registrations for one
  -- email do not both proceed; the second is told the truth about why it is waiting.
  if v_saga.executor_token_hash is not null
     and v_saga.executor_token_hash <> p_token_hash
     and v_saga.executor_expires_at is not null
     and v_saga.executor_expires_at > now() then
    return jsonb_build_object(
      'outcome', 'in_progress', 'claimed', false,
      'cursor', v_saga.provisioning_cursor, 'state', v_saga.state,
      'generation', v_saga.executor_generation
    );
  end if;

  update public.yorisou_identity_provisioning_sagas
     set executor_token_hash = p_token_hash,
         executor_generation = v_saga.executor_generation + 1,
         executor_claimed_at = now(),
         executor_expires_at = now() + make_interval(secs => p_ttl_seconds),
         attempt_count       = v_saga.attempt_count + 1,
         -- A retryable failure is a note about the PREVIOUS attempt, never an instruction about
         -- where to start. The cursor is deliberately untouched.
         state               = case when v_saga.state = 'failed_retryable'
                                    then public.yorisou_provisioning_state_for_cursor(v_saga.provisioning_cursor)
                                    else v_saga.state end,
         updated_at          = now()
   where provisioning_key = p_provisioning_key;

  return jsonb_build_object(
    'outcome', 'claimed', 'claimed', true,
    'cursor', v_saga.provisioning_cursor,
    'state', public.yorisou_provisioning_state_for_cursor(v_saga.provisioning_cursor),
    'generation', v_saga.executor_generation + 1,
    'accountId', v_saga.account_id,
    'attemptCount', v_saga.attempt_count + 1,
    'resumed', v_saga.provisioning_cursor <> 'account_creation'
  );
end $function$

CREATE OR REPLACE FUNCTION public.yorisou_provisioning_purge_for_owner(p_account_id text DEFAULT NULL::text, p_owner_fingerprint text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_rows int;
begin
  if p_account_id is null and p_owner_fingerprint is null then
    raise exception 'provisioning_purge_target_required';
  end if;
  delete from public.yorisou_identity_provisioning_sagas
   where (p_account_id is not null and account_id = p_account_id)
      or (p_owner_fingerprint is not null and owner_fingerprint = p_owner_fingerprint);
  get diagnostics v_rows = row_count;
  return v_rows;
end $function$

CREATE OR REPLACE FUNCTION public.yorisou_provisioning_record_failure(p_provisioning_key text, p_token_hash text, p_generation integer, p_failure_class text, p_error_code text DEFAULT NULL::text, p_terminal boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_saga public.yorisou_identity_provisioning_sagas%rowtype;
begin
  select * into v_saga from public.yorisou_identity_provisioning_sagas
   where provisioning_key = p_provisioning_key for update;
  if not found then raise exception 'provisioning_saga_not_found'; end if;
  if v_saga.state = 'completed' then
    -- A completed provisioning cannot be un-completed by a late failure report from a lost attempt.
    return jsonb_build_object('state', v_saga.state, 'cursor', v_saga.provisioning_cursor);
  end if;
  if v_saga.executor_token_hash is distinct from p_token_hash
     or v_saga.executor_generation is distinct from p_generation then
    raise exception 'provisioning_executor_mismatch';
  end if;

  update public.yorisou_identity_provisioning_sagas
     set state           = case when p_terminal then 'failed_terminal' else 'failed_retryable' end,
         failure_class   = p_failure_class,
         last_error_code = left(coalesce(p_error_code, ''), 80),
         -- Released, so the retry does not have to outlive the TTL to take over.
         executor_token_hash = null,
         executor_expires_at = null,
         updated_at      = now()
   where provisioning_key = p_provisioning_key;

  return jsonb_build_object(
    'state', case when p_terminal then 'failed_terminal' else 'failed_retryable' end,
    'cursor', v_saga.provisioning_cursor
  );
end $function$

CREATE OR REPLACE FUNCTION public.yorisou_values_assessment_correct(p_owner_account_id text, p_assessment_id uuid, p_answers jsonb, p_result_id text, p_is_mixed boolean, p_expected_method_id text, p_expected_method_version text, p_expected_bank_version text, p_expected_scoring_version text, p_expected_result_schema_version text, p_expected_bank_content_hash text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_record public.yorisou_values_assessments%rowtype;
  v_next integer;
begin
  select * into v_record from public.yorisou_values_assessments
  where id = p_assessment_id and owner_account_id = p_owner_account_id
  for update;
  if not found then
    raise exception 'values_record_not_found';
  end if;
  -- YV-C2/YV-C6: all SIX provenance fields re-verified against the locked row
  -- (method_id included — the CHECK constraint is not a substitute for the
  -- explicit six-field mutation contract).
  if v_record.method_id <> p_expected_method_id
     or v_record.method_version <> p_expected_method_version
     or v_record.bank_version <> p_expected_bank_version
     or v_record.scoring_version <> p_expected_scoring_version
     or v_record.result_schema_version <> p_expected_result_schema_version
     or v_record.bank_content_hash <> p_expected_bank_content_hash then
    raise exception 'values_record_contract_version_mismatch';
  end if;
  -- YV-C1: reject a no-op answer correction (byte-equivalent answers).
  if v_record.answers = p_answers then
    raise exception 'values_no_answer_change';
  end if;
  v_next := v_record.current_version + 1;
  insert into public.yorisou_values_assessment_versions
    (assessment_id, version, answers, result_id, is_mixed, confirmation, reason_code, produced_at)
  values (p_assessment_id, v_next, p_answers, p_result_id, coalesce(p_is_mixed, false), v_record.confirmation, 'user_correction', now());
  update public.yorisou_values_assessments
  set answers = p_answers,
      result_id = p_result_id,
      is_mixed = coalesce(p_is_mixed, false),
      current_version = v_next,
      updated_at = now()
  where id = p_assessment_id;
  insert into public.yorisou_values_assessment_events
    (assessment_id, owner_account_id, event_type, version, reason_code)
  values (p_assessment_id, p_owner_account_id, 'corrected', v_next, 'user_correction');
  return v_next;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_values_assessment_create(p_owner_account_id text, p_method_version text, p_bank_version text, p_scoring_version text, p_result_schema_version text, p_answers jsonb, p_result_id text, p_is_mixed boolean, p_confirmation text, p_bank_content_hash text, p_produced_at text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
  v_produced timestamptz := coalesce(p_produced_at::timestamptz, now());
begin
  if p_owner_account_id is null or length(p_owner_account_id) = 0 then
    raise exception 'values_owner_required';
  end if;
  insert into public.yorisou_values_assessments
    (owner_account_id, method_version, bank_version, scoring_version, result_schema_version,
     bank_content_hash, answers, result_id, is_mixed, confirmation, current_version, produced_at)
  values
    (p_owner_account_id, p_method_version, p_bank_version, p_scoring_version, p_result_schema_version,
     p_bank_content_hash, p_answers, p_result_id, coalesce(p_is_mixed, false), coalesce(p_confirmation, 'skipped'), 1, v_produced)
  returning id into v_id;
  insert into public.yorisou_values_assessment_versions
    (assessment_id, version, answers, result_id, is_mixed, confirmation, reason_code, produced_at)
  values (v_id, 1, p_answers, p_result_id, coalesce(p_is_mixed, false), coalesce(p_confirmation, 'skipped'), 'initial', v_produced);
  insert into public.yorisou_values_assessment_events
    (assessment_id, owner_account_id, event_type, version, reason_code)
  values (v_id, p_owner_account_id, 'created', 1, 'initial');
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_values_assessment_delete(p_owner_account_id text, p_assessment_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_record public.yorisou_values_assessments%rowtype;
begin
  select * into v_record from public.yorisou_values_assessments
  where id = p_assessment_id and owner_account_id = p_owner_account_id
  for update;
  if not found then
    return false;
  end if;
  perform set_config('yorisou.values_governed_erase', 'on', true);
  delete from public.yorisou_values_assessment_versions where assessment_id = v_record.id;
  delete from public.yorisou_values_assessments where id = v_record.id;
  delete from public.yorisou_values_assessment_events where assessment_id = v_record.id;
  perform set_config('yorisou.values_governed_erase', 'off', true);
  insert into public.yorisou_values_assessment_events
    (assessment_id, owner_account_id, event_type, version, reason_code, retention_expires_at)
  values (v_record.id, p_owner_account_id, 'deleted', v_record.current_version, 'user_deleted', now() + interval '12 months');
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_values_assessment_set_confirmation(p_owner_account_id text, p_assessment_id uuid, p_confirmation text, p_expected_method_id text, p_expected_method_version text, p_expected_bank_version text, p_expected_scoring_version text, p_expected_result_schema_version text, p_expected_bank_content_hash text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_record public.yorisou_values_assessments%rowtype;
  v_reason text;
begin
  if p_confirmation not in ('confirmed', 'not_quite', 'skipped') then
    raise exception 'values_invalid_confirmation';
  end if;
  select * into v_record from public.yorisou_values_assessments
  where id = p_assessment_id and owner_account_id = p_owner_account_id
  for update;
  if not found then
    raise exception 'values_record_not_found';
  end if;
  -- YV-C2/YV-C6: all SIX provenance fields re-verified against the locked row.
  if v_record.method_id <> p_expected_method_id
     or v_record.method_version <> p_expected_method_version
     or v_record.bank_version <> p_expected_bank_version
     or v_record.scoring_version <> p_expected_scoring_version
     or v_record.result_schema_version <> p_expected_result_schema_version
     or v_record.bank_content_hash <> p_expected_bank_content_hash then
    raise exception 'values_record_contract_version_mismatch';
  end if;
  -- YV-C8: idempotent — requesting the confirmation the record already holds is a
  -- truthful no-op success. No event is appended, updated_at is NOT bumped, no
  -- version change. Only a genuine state change emits ONE confirmation_changed event.
  if v_record.confirmation = p_confirmation then
    return p_confirmation;
  end if;
  v_reason := case p_confirmation
    when 'confirmed' then 'user_confirmed'
    when 'not_quite' then 'user_not_quite'
    else 'user_skipped'
  end;
  update public.yorisou_values_assessments
  set confirmation = p_confirmation, updated_at = now()
  where id = p_assessment_id;
  insert into public.yorisou_values_assessment_events
    (assessment_id, owner_account_id, event_type, version, reason_code)
  values (p_assessment_id, p_owner_account_id, 'confirmation_changed', v_record.current_version, v_reason);
  return p_confirmation;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_values_block_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'DELETE' and current_setting('yorisou.values_governed_erase', true) = 'on' then
    return old;
  end if;
  raise exception 'append_only: % on % is not permitted', tg_op, tg_table_name;
end;
$function$

CREATE OR REPLACE FUNCTION public.yorisou_values_tombstone_purge_expired(p_limit integer DEFAULT 500)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_deleted integer;
begin
  if p_limit is null or p_limit < 1 or p_limit > 5000 then
    raise exception 'values_purge_invalid_limit';
  end if;
  perform set_config('yorisou.values_governed_erase', 'on', true);
  with expired as (
    select id from public.yorisou_values_assessment_events
    where event_type = 'deleted' and retention_expires_at is not null and retention_expires_at <= now()
    order by retention_expires_at limit p_limit for update
  )
  delete from public.yorisou_values_assessment_events e using expired where e.id = expired.id;
  get diagnostics v_deleted = row_count;
  perform set_config('yorisou.values_governed_erase', 'off', true);
  return v_deleted;
end;
$function$
